import{_ as s,o as a,c as n,a as r}from"./app.DkoUFz-u.js";const c=JSON.parse('{"title":"🔍 可观测性：链路追踪采样策略完全指南","description":"","frontmatter":{},"headers":[],"relativePath":"backend/observability/tracing/sampling.md","filePath":"backend/observability/tracing/sampling.md"}'),o={name:"backend/observability/tracing/sampling.md"};function l(i,t,e,g,d,h){return a(),n("div",null,[...t[0]||(t[0]=[r(`<p>理解和掌握链路追踪中的采样策略，对于构建高效、可控的可观测体系至关重要。下面这份学习笔记梳理了采样的核心知识、不同策略的优劣以及业界实践，希望能帮助你建立系统性的理解。</p><h1 id="🔍-可观测性-链路追踪采样策略完全指南" tabindex="-1">🔍 可观测性：链路追踪采样策略完全指南 <a class="header-anchor" href="#🔍-可观测性-链路追踪采样策略完全指南" aria-label="Permalink to &quot;🔍 可观测性：链路追踪采样策略完全指南&quot;">​</a></h1><h2 id="_1️⃣-为什么需要采样" tabindex="-1">1️⃣ 为什么需要采样 <a class="header-anchor" href="#_1️⃣-为什么需要采样" aria-label="Permalink to &quot;1️⃣ 为什么需要采样&quot;">​</a></h2><p>在分布式系统中，面对海量请求产生的巨大链路数据，全量采集会面临诸多挑战：</p><ul><li><p><strong>存储成本压力</strong>：全量采集调用链数据会产生巨大的存储成本。以一个具体案例为例，某系统链路调用量4000 QPS，每个调用产生约30个Span，每个Span约500 Bytes，一天产生的数据量就高达<strong>4.7 TiB</strong>。若有100个调用链路入口需要全量采集，每天则可能产生<strong>400 TiB</strong>以上的数据。</p></li><li><p><strong>系统性能影响</strong>：全量采集会给每个业务服务的<strong>网络I/O</strong>以及链路追踪服务的<strong>计算和存储</strong>带来压力。</p></li><li><p><strong>极低的信噪比</strong>：根据伴鱼的实践经验，保守假设平均每个HTTP API服务的总QPS为100，完整存下全量数据需要10TB/天；乐观假设100名服务器研发每人每天查看1条trace，则整体<strong>信噪比仅千万分之一</strong>，投入产出比很低。</p></li></ul><h2 id="_2️⃣-采样的关键决策点" tabindex="-1">2️⃣ 采样的关键决策点 <a class="header-anchor" href="#_2️⃣-采样的关键决策点" aria-label="Permalink to &quot;2️⃣ 采样的关键决策点&quot;">​</a></h2><p>制定采样策略时，需要考虑以下几个关键维度：</p><ul><li><strong>采样时机</strong>：决定在链路的哪个阶段做出采样决策（头部、尾部或单元采样）。</li><li><strong>连贯性</strong>：是否保证整个调用链的完整性。</li><li><strong>策略灵活性</strong>：能否根据业务需求动态调整采样规则。</li><li><strong>资源开销</strong>：在业务服务、网络传输和服务端之间的平衡。</li></ul><h2 id="_3️⃣-采样策略分类" tabindex="-1">3️⃣ 采样策略分类 <a class="header-anchor" href="#_3️⃣-采样策略分类" aria-label="Permalink to &quot;3️⃣ 采样策略分类&quot;">​</a></h2><p>根据采样决策的时机和方式，主要分为三大类策略：</p><h3 id="_3-1-头部采样-head-based-sampling" tabindex="-1">3.1 头部采样 (Head-based Sampling) <a class="header-anchor" href="#_3-1-头部采样-head-based-sampling" aria-label="Permalink to &quot;3.1 头部采样 (Head-based Sampling)&quot;">​</a></h3><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span class="__shiki_140thh">flowchart TD</span></span>
<span class="line"><span class="__shiki_140thh">    A[请求进入入口服务] --&gt; B{采样决策}</span></span>
<span class="line"><span class="__shiki_140thh">    B -- 采样 --&gt; C[标记并传递采样上下文]</span></span>
<span class="line"><span class="__shiki_140thh">    C --&gt; D[下游服务继承采样]</span></span>
<span class="line"><span class="__shiki_140thh">    B -- 不采样 --&gt; E[丢弃数据]</span></span></code></pre></div><p>头部采样在<strong>请求入口处</strong>就决定整条链路是否采样。</p><ul><li><p><strong>优点</strong>：</p><ul><li>显著降低业务服务器的<strong>网络I/O开销</strong></li><li>减少服务端的<strong>存储和计算开销</strong></li></ul></li><li><p><strong>缺点</strong>：</p><ul><li>采样发生在链路产生初期，<strong>命中异常和慢响应的几率低</strong></li><li>可能错过<strong>关键问题链路</strong>，影响故障排查</li></ul></li><li><p><strong>增强方案</strong>：配合<strong>异常回溯上报</strong>机制，下游链路出现异常后，可以动态扭转上游链路的采样状态。</p></li></ul><h3 id="_3-2-尾部采样-tail-based-sampling" tabindex="-1">3.2 尾部采样 (Tail-based Sampling) <a class="header-anchor" href="#_3-2-尾部采样-tail-based-sampling" aria-label="Permalink to &quot;3.2 尾部采样 (Tail-based Sampling)&quot;">​</a></h3><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span class="__shiki_140thh">flowchart TD</span></span>
<span class="line"><span class="__shiki_140thh">    A[请求经过完整链路] --&gt; B[所有Span上报到Collector]</span></span>
<span class="line"><span class="__shiki_140thh">    B --&gt; C[根据预设规则分析]</span></span>
<span class="line"><span class="__shiki_140thh">    C --&gt; D{是否符合采样条件}</span></span>
<span class="line"><span class="__shiki_140thh">    D -- 是 --&gt; E[保留完整链路]</span></span>
<span class="line"><span class="__shiki_140thh">    D -- 否 --&gt; F[丢弃数据]</span></span></code></pre></div><p>尾部采样在<strong>请求处理完成后</strong>，根据预设规则决定是否保留链路。</p><ul><li><p><strong>优点</strong>：</p><ul><li>可<strong>精准采集</strong>异常、慢响应或有业务价值的链路</li><li>有效降低<strong>存储成本</strong>同时保留高价值数据</li></ul></li><li><p><strong>缺点</strong>：</p><ul><li>对<strong>业务服务器的网络I/O压力无缓解</strong></li><li>需要在服务端<strong>缓存所有链路数据</strong>直至做出决策</li></ul></li></ul><h3 id="_3-3-单元采样-unitary-sampling" tabindex="-1">3.3 单元采样 (Unitary Sampling) <a class="header-anchor" href="#_3-3-单元采样-unitary-sampling" aria-label="Permalink to &quot;3.3 单元采样 (Unitary Sampling)&quot;">​</a></h3><p>各个业务模块<strong>自主决定</strong>是否上报当前节点，单个节点的采样决策不影响链路上的其他服务。</p><ul><li><strong>优点</strong>：避免整体业务链路采样决策影响，节点的<strong>异常信息可以精准上报</strong></li><li><strong>缺点</strong>：<strong>链路连贯性无法保证</strong>，无法支持根据上下游进行有效根因分析</li></ul><h2 id="_4️⃣-具体采样算法与实践" tabindex="-1">4️⃣ 具体采样算法与实践 <a class="header-anchor" href="#_4️⃣-具体采样算法与实践" aria-label="Permalink to &quot;4️⃣ 具体采样算法与实践&quot;">​</a></h2><h3 id="_4-1-基础采样算法" tabindex="-1">4.1 基础采样算法 <a class="header-anchor" href="#_4-1-基础采样算法" aria-label="Permalink to &quot;4.1 基础采样算法&quot;">​</a></h3><table tabindex="0"><thead><tr><th><strong>算法类型</strong></th><th><strong>实现方式</strong></th><th><strong>适用场景</strong></th></tr></thead><tbody><tr><td><strong>固定概率采样</strong></td><td>按固定概率采样，如采样率10%</td><td>通用场景，流量均匀的系统</td></tr><tr><td><strong>简单随机采样</strong></td><td>每个请求独立随机决定是否采样</td><td>基础采样需求</td></tr><tr><td><strong>限流采样</strong></td><td>保证每个进程每隔一段时间最多采k个</td><td>高流量服务，保护后端系统</td></tr><tr><td><strong>周期性完整采样</strong></td><td>单位时间内只采集固定数量事件，超出的丢弃</td><td>控制峰值流量下的数据量</td></tr></tbody></table><h3 id="_4-2-高级采样策略" tabindex="-1">4.2 高级采样策略 <a class="header-anchor" href="#_4-2-高级采样策略" aria-label="Permalink to &quot;4.2 高级采样策略&quot;">​</a></h3><ul><li><p><strong>基于条件的采样</strong>：根据特定条件采样，如<strong>耗时阈值</strong>（&gt;300ms）、<strong>HTTP状态码</strong>（400-600）、<strong>可用区</strong>等</p></li><li><p><strong>自适应采样</strong>：按单位时间采集固定数目的Trace为目标，例如单实例100条/min</p></li><li><p><strong>动态采样策略</strong>：通过采样策略树和执行轨迹图两种数据结构自动调整跟踪采样率，提高异常执行的跟踪占比</p></li><li><p><strong>染色采样</strong>：对于特定标记的请求（如测试泳道、重要用户）100%采样</p></li><li><p><strong>应急采样</strong>：请求传递过程中检测到错误或异常时，<strong>强制采样</strong>该请求</p></li></ul><h2 id="_5️⃣-业界实践案例" tabindex="-1">5️⃣ 业界实践案例 <a class="header-anchor" href="#_5️⃣-业界实践案例" aria-label="Permalink to &quot;5️⃣ 业界实践案例&quot;">​</a></h2><h3 id="_5-1-头部采样增强方案" tabindex="-1">5.1 头部采样增强方案 <a class="header-anchor" href="#_5-1-头部采样增强方案" aria-label="Permalink to &quot;5.1 头部采样增强方案&quot;">​</a></h3><p><strong>SkyWalking</strong>：</p><ul><li>支持简单的采样百分比</li><li>允许错误链路强制采样 (<code>forceSampleErrorSegment</code>)</li><li>对<strong>慢SQL采样</strong>特别优化</li></ul><p><strong>Jaeger</strong>：</p><ul><li>支持Const（全采样或不采样）、Probabilistic（按固定概率采样）、Rate Limiting（限流采样）三种方式</li><li>支持<strong>远程动态调整</strong>采样方式</li></ul><h3 id="_5-2-尾部采样实践" tabindex="-1">5.2 尾部采样实践 <a class="header-anchor" href="#_5-2-尾部采样实践" aria-label="Permalink to &quot;5.2 尾部采样实践&quot;">​</a></h3><p><strong>货拉拉</strong>：</p><ul><li>实现<strong>差异化完成链路采样</strong></li><li>保证<strong>1小时以内</strong>的数据全量保存（热数据）</li><li>一小时以外的数据，只保留<strong>错、慢、核心服务</strong>请求Trace（冷数据）</li><li>将整体<strong>存储成本降低了60%</strong></li></ul><p><strong>腾讯云APM</strong>：</p><ul><li>支持<strong>异常、慢响应链路全保留</strong></li><li>可配置<strong>核心业务逻辑全保留</strong></li><li><strong>重大事件保障</strong>期间全面监控</li></ul><h3 id="_5-3-自适应采样实践" tabindex="-1">5.3 自适应采样实践 <a class="header-anchor" href="#_5-3-自适应采样实践" aria-label="Permalink to &quot;5.3 自适应采样实践&quot;">​</a></h3><p><strong>阿里云ARMS自适应采样</strong>：</p><ul><li><strong>特定接口全采样</strong>：通过自定义接口名、前后缀标记需要100%采样的接口</li><li><strong>接口Top N采样</strong>：使用变种LFU算法，单位时间内只对每个接口的有限条目请求采样</li><li><strong>小流量兜底采样</strong>：单位时间内，每个接口至少保证有<strong>1次采样</strong></li></ul><h2 id="_6️⃣-采样策略选择指南" tabindex="-1">6️⃣ 采样策略选择指南 <a class="header-anchor" href="#_6️⃣-采样策略选择指南" aria-label="Permalink to &quot;6️⃣ 采样策略选择指南&quot;">​</a></h2><h3 id="_6-1-基于业务场景的策略选择" tabindex="-1">6.1 基于业务场景的策略选择 <a class="header-anchor" href="#_6-1-基于业务场景的策略选择" aria-label="Permalink to &quot;6.1 基于业务场景的策略选择&quot;">​</a></h3><table tabindex="0"><thead><tr><th><strong>场景类型</strong></th><th><strong>推荐策略</strong></th><th><strong>配置建议</strong></th></tr></thead><tbody><tr><td><strong>核心业务链路</strong></td><td>尾部采样 + 高采样率</td><td>关键接口可配置80%-100%采样率</td></tr><tr><td><strong>高流量入口</strong></td><td>头部采样 + 限流</td><td>控制整体数据量，设置较低采样率</td></tr><tr><td><strong>边缘业务</strong></td><td>单元采样/头部采样</td><td>配置较低采样率（1%-5%）</td></tr><tr><td><strong>重大事件保障</strong></td><td>临时全采样/染色采样</td><td>特定时间段或特定标签全量采集</td></tr><tr><td><strong>小流量接口</strong></td><td>自适应采样兜底</td><td>确保每个接口单位时间至少有一次采样</td></tr></tbody></table><h3 id="_6-2-成本效益优化策略" tabindex="-1">6.2 成本效益优化策略 <a class="header-anchor" href="#_6-2-成本效益优化策略" aria-label="Permalink to &quot;6.2 成本效益优化策略&quot;">​</a></h3><ul><li><strong>入口应用控制</strong>：通过调整<strong>入口应用</strong>的采样率可显著控制整体可观测数据采集量</li><li><strong>接口粒度配置</strong>：针对<strong>核心接口</strong>定向配置高比例采样率，非核心接口降低采样率</li><li><strong>价值导向采集</strong>：根据货拉拉经验，<strong>80%~90%的Trace数据都是无价值的</strong>，聚焦错、慢、核心服务请求</li></ul><h2 id="_7️⃣-总结" tabindex="-1">7️⃣ 总结 <a class="header-anchor" href="#_7️⃣-总结" aria-label="Permalink to &quot;7️⃣ 总结&quot;">​</a></h2><p>采样策略的选择本质上是在<strong>观测价值</strong>与<strong>资源成本</strong>之间寻求平衡。有效的采样策略应该：</p><ol><li>确保<strong>高价值链路</strong>（异常、慢调用、核心业务）被高效捕获</li><li>在<strong>成本可控</strong>的前提下提供足够的故障排查信息</li><li>具备<strong>灵活性</strong>，能根据不同场景动态调整</li><li>保持关键链路的<strong>连贯性</strong>，支持端到端问题定位</li></ol><p>通过组合多种采样策略，因地制宜地配置，才能在可控的资源开销内，最大程度保留事故相关链路，支持高效的故障排查和性能监控。</p>`,49)])])}const _=s(o,[["render",l]]);export{c as __pageData,_ as default};
